const captchaModel = require('./captchaModel.json');

/**
 * Solves an SVG captcha generated by svg-captcha / opentype.js.
 * @param {string} svgContent - Raw SVG XML text
 * @returns {string|null} - Solved text or null if unresolved characters exist
 */
function solveSvg(svgContent) {
  if (!svgContent || typeof svgContent !== 'string') return null;

  // Characters in svg-captcha are paths with fill and NO stroke
  const pathRegex = /<path(?![^>]*stroke)[^>]*d="([^"]+)"/g;
  let match;
  const chars = [];

  while ((match = pathRegex.exec(svgContent)) !== null) {
    const d = match[1];
    // Find initial X coordinate to order characters from left to right
    const coordMatch = d.match(/M\s*([\d\.]+)/);
    const x = coordMatch ? parseFloat(coordMatch[1]) : 0;
    // Extract vector command sequence (stripping all numbers, dots, spaces)
    const pattern = d.replace(/[\d.\s]/g, '');
    const char = captchaModel[pattern] || null;

    if (!char) {
      return null; // Unknown glyph pattern, signal failure so caller can retry
    }

    chars.push({ x, char });
  }

  if (chars.length === 0) return null;

  // Sort characters by X position (left to right)
  chars.sort((a, b) => a.x - b.x);
  return chars.map((c) => c.char).join('');
}

/**
 * Solves an SVG captcha from a Data URI or Base64 string.
 * @param {string} base64OrDataUri
 * @returns {string|null}
 */
function solveBase64(base64OrDataUri) {
  if (!base64OrDataUri || typeof base64OrDataUri !== 'string') return null;
  const cleanB64 = base64OrDataUri.replace(/^data:image\/svg\+xml;base64,/, '').trim();
  const svgText = Buffer.from(cleanB64, 'base64').toString('utf8');
  return solveSvg(svgText);
}

module.exports = {
  solveSvg,
  solveBase64,
};
